"""Refresh final documents using actual live-phase counts; preserve historical versions."""
import collections,json
from pathlib import Path
import report
from analyze import H,read,raw

def write(n,text):(H/n).write_text(text.strip()+'\n',encoding='utf8')
def main():
 report.main();status=read(H/'analysis_status.json');groups=read(H/'aggregate_metrics.json')['groups'];live=raw('../live_campaign/raw/responses.jsonl');done=len(live)==1330 and (H/'live_campaign/completion.json').exists()
 baseline=[g for g in groups if g['condition'] in ('B1','B2','B3','B4')];ablations=[g for g in groups if g['condition'] in ('B4','A1','A2','A12')]
 at='| Model | Condition | Recorded / planned | Failed | Reference-match proxy | Extractor hits | Warnings | Median wall (s) |\n|---|---|---:|---:|---:|---:|---:|---:|\n'
 for g in ablations:at+=f"| {g['model']} | {g['condition']} | {g['attempted_n']}/133 | {g['failed_n']} | {g['reference_match_proxy_n']}/{g['attempted_n']} | {g.get('extractor_hit_n',0)} | {g.get('warning_answer_n',0)} | {g['median_wall_s']:.3f} |\n"
 note=f'''\n## Restored database and live-phase update\nDatabase access was restored. All public-table fingerprints, selected SQL records/chunks and model digests match the earlier capture; 195 AI module hashes remain unchanged. See live_campaign/evidence/phase_equivalence.json. Only the ten missing smoke keys were executed; earlier completed keys were reused. The live campaign has {len(live)}/1,330 saved model-workflow attempts; completion={done}. B1 and frozen-corpus RAG retain their 532 completed attempts. No original result, gold answer or production source was changed. B4 denotes the current full AI graph and gates with frozen external chain-report replay and trusted in-process operator context. It is not a live end-to-end C4/C7/authentication test. The archived verifier source differs from current C7 source; current reconciliation findings remain separate (live_campaign/evidence/chain_replay_scope.json).\n\nThe new direct-SQL baseline executed 26/26 applicable DB questions with 26/26 exact scalar agreements, zero LLM calls. Its hand-coded field selector is an oracle-like lookup baseline, not general text-to-SQL reasoning or independent gold validation. Other categories are outside this baseline's applicability. Four proposal-type items (DB-008/018/028/038) expect a database field absent from registered AI tool projections and the archived chain reports. They remain in all 133-item exploratory denominators, with access-aware expected-behavior adjudication pending; gold was not changed. Thus the SQL oracle has a broader projection for these four items and is not an equivalent-tool baseline. See live_campaign/evidence/proposal_type_access_check.json.\n\nLive SQL and fixed-corpus RAG use identical captured facts/chunks, but execution phases and retrieval implementations differ. Raw outputs support independent reanalysis; live inference reproduction additionally requires the original authorized PostgreSQL/index snapshot and configuration, which are not a self-contained public database image. Model aliases/templates/weight-blob identifiers are frozen in evidence/model_recreation_metadata.json. Wire request digests were computed before privacy redaction; public sanitized payloads may therefore have different hashes, separately counted from model/configuration mismatches. Effective model attribution uses normalized provider requests and provider responses; application model_used/trace labels can retain the originally requested default name under the research interceptor. These are model regimes, not an isolated parameter-count scaling experiment. Decoding/model versions match; hardware residency, cache state and queueing are not controlled enough for a causal latency-overhead claim. Operational completed/returned counts include bounded fallback text and do not establish task success; worker failures and warnings remain in raw records. Every case uses the declared model/call/deadline budgets. The legacy live-run started_utc field is assigned at completion; it is retained unchanged and labelled as a completion timestamp in derived metrics. Monotonic wall_ms remains the observed duration. Full baselines and ablations are real model executions, not copied predictions.\n'''
 for name in ['BENCHMARK_AUDIT.md','STATISTICAL_ANALYSIS.md','FAILURE_ANALYSIS.md','Q1_MANUSCRIPT_RESULTS_REVISION.md','FINAL_SCIENTIFIC_TABLES.md']:
  text=(H/name).read_text(encoding='utf8')
  text=text.replace('B3/B4 benchmark and new SQL baseline are infrastructure-blocked.','The earlier infrastructure block was resolved; live-phase execution is reported below.')
  text=text.replace('B3/B4 cohort and SQL are blocked.','Live-phase execution is reported below.')
  text=text.replace('No new full-workflow accuracy attribution is possible without the blocked B3/B4 cohort.','New full-workflow findings remain exploratory and await independent answer adjudication.')
  text=text.replace('database outage prevented the new full-workflow campaign','database outage delayed the live full-workflow campaign')
  text=text.replace('blocked full-workflow runs','phase-specific execution conditions')
  text=text.replace('There is no 133-question ablation comparison.','The live-phase ablation counts are reported below.')
  text=text.replace('Direct SQL is blocked; B2 is also','Direct SQL is reported below; B2 is also')
  (H/name).write_text(text+note,encoding='utf8')
 with (H/'FINAL_SCIENTIFIC_TABLES.md').open('a',encoding='utf8') as f:f.write('\n## Live-phase ablation table\n'+at+'\nB4 is the same control already counted in the baseline table; it is not another independent replicate. A2 removes only M7 blocking_flags, retaining structural/currency guards.\n')
 diagnostic='''\n## Provisional output review and arithmetic coverage\nEight predeclared purposive answer targets were reviewed by the research assistant AI, without independent human adjudication. The four 0.6B answers included one factually correct budget answer lacking canonical citations, two incorrect answers and one partial answer. The four 4B targets included three factually correct answers with noncanonical citations and one timeout. This is a diagnostic sample, not cohort accuracy. Four selected 0.6B numeric atoms included two supported and two contradicted claims; see diagnostic_answer_review.csv and raw/diagnostic_claim_review.json.\n\nA controlled replay found that both the legacy amount guard and M7 flag check withhold the correct derived sum EUR 6,000 + EUR 3,000 = EUR 9,000 when 9,000 is absent from the literal sources. This documents a direct-value coverage/design limitation, not evidence that the arithmetic is wrong. A2 retains the legacy guard, so its results measure the incremental M7 gate, not removal of all numerical verification. No production fix was applied. See raw/arithmetic_guard_replay.json.\n'''
 with (H/'FAILURE_ANALYSIS.md').open('a',encoding='utf8') as f:f.write(diagnostic)
 with (H/'Q1_MANUSCRIPT_RESULTS_REVISION.md').open('a',encoding='utf8') as f:f.write(diagnostic)
 with (H/'REVIEWER_RESPONSE_MATRIX.md').open('a',encoding='utf8') as f:f.write(note+'\nInterpret the M2/M3 infrastructure-blocked entries above as historical status, superseded by these actual live-phase counts. Independent whole-answer support adjudication remains pending.\n')
 write('FINAL_READINESS_REPORT.md',f'''# Readiness decision\n**Exploratory/design-and-feasibility. NO-GO for independently human-validated confirmatory AI claims.**\n\nB1 plus frozen-corpus RAG: {status['b1_n']+status['b2_n']}/532 recorded attempts. Live B3/B4/A1/A2/A12: {len(live)}/1,330 recorded attempts. Full planned model-workflow count: 1,862. Live campaign complete: {done}. The SQL baseline recorded {status.get('direct_SQL_n',0)}/26 applicable cases, all exact scalar matches. All failures remain in denominators. No completed model condition was unnecessarily repeated.\n\nFour saved 0.6B B4 diagnostic targets show unrequested planner expansion, missed task coverage and treating budget-line ordinals as monetary inputs (raw/current_workflow_diagnostic.json). The campaign deliberately normalizes every chat stage to temperature 0.6, overriding the production planner's temperature 0; this is a homogeneous-decoding research variant, not a default-configuration production accuracy estimate. No production fix or result relabelling was made. The ten missing development smoke keys were targeted; earlier keys were reused. New software tests: nine adapter, nine analysis, one frozen-adapter and two SQL-selector tests passed. Prior 169 artifact hashes were verified. Source freeze: three PDF files, six exact normalized page chunks; 48/48 original-to-preflight SQL field matches; live-phase public table fingerprints and source code remain equal to the prior capture.\n\nAll 133 formerly reserved questions are now exploratory-exposed in the separate ledger. Human annotations and independent adjudication remain absent; no human agreement or final benchmark semantic accuracy is claimed. Automatic reference matching and the gate's own flags do not establish factual correctness. Eight purposive AI-assisted reviews are separately labelled. The claim challenge has 26 actual checks and a 24-case source-valid provisional panel.\n\nDocker's earlier outage was resolved by external restoration; no blocked socket deletion was performed by this agent. Current limitations: human ground truth, four source-access alignment flags, low source diversity/shared facts, frozen-versus-live retrieval phases, cache/GPU/queue effects, single-seed observations, partial interrupted-smoke start accounting, one RPC provider, arithmetic/claim parsing coverage and missing manuscript source. No production data, contracts, credentials or source code were modified.\n\nUse FINAL_SCIENTIFIC_TABLES.md and Q1_MANUSCRIPT_RESULTS_REVISION.md with these limitations; model outputs support exploratory comparisons, not an independently validated confirmatory contribution.\n''')
 print(json.dumps({'live_records':len(live),'live_complete':done,'total_model_records':status['benchmark_records'],'SQL_records':status.get('direct_SQL_n',0)}))
if __name__=='__main__':main()
